--
-- Table structure for table `etudiant`
--

DROP TABLE IF EXISTS `etudiant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `etudiant` (
  `matriculeEtudiant` varchar(20) NOT NULL,
  `nom` varchar(100) DEFAULT NULL,
  `nomArabe` varchar(100) NOT NULL COMMENT 'nom en arabe pour les impressions en arabe',
  `niveau` varchar(20) DEFAULT NULL,
  `prenom` varchar(45) DEFAULT NULL,
  `prenomArabe` varchar(60) NOT NULL,
  `surnom` varchar(45) DEFAULT NULL,
  `sexe` varchar(1) DEFAULT NULL,
  `dateNaissance` date DEFAULT NULL,
  `lieuNaissance` varchar(90) DEFAULT NULL,
  `lieuNaissance_ar` varchar(50) NOT NULL,
  `NIN` varchar(45) DEFAULT NULL,
  `infoBac` int(11) DEFAULT NULL,
  `login` varchar(45) DEFAULT NULL,
  `pass` varchar(45) DEFAULT NULL,
  `nbreAcces` tinyint(1) NOT NULL DEFAULT 0,
  `email` varchar(45) DEFAULT NULL,
  `idAdresse` int(11) DEFAULT NULL,
  `idAdresseParent` int(11) DEFAULT NULL,
  `telephone` varchar(45) DEFAULT NULL,
  `telephone2` varchar(45) DEFAULT NULL,
  `telParents` varchar(45) DEFAULT NULL,
  `telUrgence` varchar(45) DEFAULT NULL,
  `contactUrgence` varchar(45) DEFAULT NULL,
  `lienParenteUrgence` varchar(45) DEFAULT NULL,
  `raisonInactif` varchar(160) DEFAULT NULL,
  `actif` tinyint(1) DEFAULT NULL,
  `nationalite` varchar(150) DEFAULT NULL,
  `photoEtudiant` varchar(45) NOT NULL,
  `nomParents` varchar(90) DEFAULT NULL,
  `annee_inscription` int(11) NOT NULL,
  `created_by` varchar(20) NOT NULL,
  `dateInscription` datetime NOT NULL DEFAULT current_timestamp(),
  `prenomPere_fr` varchar(100) NOT NULL,
  `prenomPere_ar` varchar(100) NOT NULL,
  `creePar` varchar(45) DEFAULT NULL,
  `dateCreation` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `modifPar` varchar(45) DEFAULT NULL,
  `dateModif` timestamp NOT NULL DEFAULT current_timestamp(),
  `voie` int(11) DEFAULT NULL,
  PRIMARY KEY (`matriculeEtudiant`),
  KEY `fk_infoBac` (`infoBac`),
  KEY `fk_idAdresse1` (`idAdresse`),
  KEY `fk_idAdresseParent` (`idAdresseParent`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

