DROP TABLE IF EXISTS `etudiant_23`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `etudiant_23` (
  `matriculeEtudiant` int(11) NOT NULL,
  `nom` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `nomArabe` varchar(60) CHARACTER SET utf8 NOT NULL COMMENT 'nom en arabe pour les impressions en arabe',
  `prenom` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `prenomArabe` varchar(60) CHARACTER SET utf8 NOT NULL,
  `surnom` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `sexe` varchar(1) CHARACTER SET utf8 DEFAULT NULL,
  `dateNaissance` date DEFAULT NULL,
  `lieuNaissance` varchar(90) CHARACTER SET utf8 DEFAULT NULL,
  `lieuNaissance_ar` varchar(50) CHARACTER SET utf8 NOT NULL,
  `NIN` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `infoBac` int(11) DEFAULT NULL,
  `login` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `pass` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `nbreAcces` tinyint(1) NOT NULL DEFAULT 0,
  `email` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `idAdresse` int(11) DEFAULT NULL,
  `idAdresseParent` int(11) DEFAULT NULL,
  `telephone` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `telephone2` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `telParents` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `telUrgence` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `contactUrgence` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `lienParenteUrgence` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `raisonInactif` varchar(160) CHARACTER SET utf8 DEFAULT NULL,
  `actif` tinyint(1) DEFAULT NULL,
  `nationalite` varchar(150) CHARACTER SET utf8 DEFAULT NULL,
  `photoEtudiant` varchar(45) CHARACTER SET utf8 NOT NULL,
  `nomParents` varchar(90) CHARACTER SET utf8 DEFAULT NULL,
  `annee_inscription` int(11) NOT NULL,
  `created_by` varchar(5) CHARACTER SET utf8 NOT NULL,
  `dateInscription` datetime NOT NULL DEFAULT current_timestamp(),
  `prenomPere_fr` varchar(100) CHARACTER SET utf8 NOT NULL,
  `prenomPere_ar` varchar(100) CHARACTER SET utf8 NOT NULL,
  `creePar` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `dateCreation` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `modifPar` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `dateModif` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `voie` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
