CREATE TABLE `parametres_generaux` (
  `id_params` int(11) NOT NULL DEFAULT 0 COMMENT 'identifiant de la table: n''est pas important',
  `logo` varchar(512) NOT NULL COMMENT 'l''icone de l''institut ',
  `logo_ins_parent` varchar(100) NOT NULL,
  `nom` varchar(512) NOT NULL COMMENT 'le nom de l''institut en francais exp: "Institut Universitaire Professionnel" pour l,IUP',
  `nom_ar` varchar(512) NOT NULL COMMENT 'le nom de l''institut en arabe exp: "Institut Universitaire Professionnel" pour l,IUP',
  `abreviation_nom` varchar(16) NOT NULL COMMENT 'en francais -exp: IUP pour "Institut Universitaire Professionnel", ISCAE pour "Institut Supérieur de Comptabilité et d''Administration des Entreprises"',
  `abreviation_nom_ar` varchar(16) NOT NULL COMMENT 'l''abreviation du nom de l''institut en arabe ',
  `nom_ins_parent_fr` varchar(100) NOT NULL,
  `nom_ins_parent_ar` varchar(100) NOT NULL,
  `pays` varchar(256) NOT NULL COMMENT 'pays en francais',
  `pays_ar` varchar(256) NOT NULL COMMENT 'pays en arabe',
  `ville` varchar(256) NOT NULL COMMENT 'ville en francais',
  `ville_ar` varchar(256) NOT NULL COMMENT 'ville en arabe',
  `boite_postale` varchar(16) NOT NULL COMMENT 'boite postale',
  `adresse` varchar(256) DEFAULT NULL,
  `adresse_ar` varchar(100) NOT NULL DEFAULT 'شارع',
  `email` varchar(64) NOT NULL COMMENT 'l''adresse électronique',
  `telephone` varchar(16) NOT NULL COMMENT 'le numero de telephone',
  `telephone_2` varchar(13) CHARACTER SET latin1 NOT NULL,
  `siteweb` varchar(64) NOT NULL COMMENT 'le site web de l’établissement',
  `date_debut` datetime DEFAULT current_timestamp() COMMENT 'date debut de l''utilisation de ces parametres',
  `date_fin` datetime DEFAULT NULL COMMENT 'c''est la date de modification des params, si c''est null donc les params sont actifs ',
  `responsable` varchar(16) NOT NULL COMMENT 'celui qui a modifié les params',
  `modifie_par` varchar(16) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
